mapper.select:
SELECT o.id AS order_id, o.order_no, o.status, o.trade_mode, o.amount, o.item_id, s.item_title, s.item_image_url, s.item_price, u.id AS counterpart_id, u.nickname AS counterpart_nickname, u.avatar_url AS counterpart_avatar_url, o.created_at, o.updated_at FROM orders o JOIN order_snapshots s ON s.order_id = o.id
JOIN users u ON u.id = o.buyer_id WHERE o.seller_id = #{userId}
JOIN users u ON u.id = o.seller_id WHERE o.buyer_id = #{userId}
AND o.status = #{status}
ORDER BY o.created_at DESC, o.id DESC
